#include <gtest/gtest.h>
#include "storage/sstable.h"
#include <filesystem>
#include <string>

using namespace widedb::storage;
using namespace widedb::io;

static Slice s_of(const std::string& s) {
    return Slice(reinterpret_cast<const uint8_t*>(s.data()), s.size());
}

TEST(SstableLargeValueTest, ValueAtLimitIsAccepted) {
    EventLoop loop(1024);
    std::string filepath = "test_lv_1.sst";
    auto builder = std::make_shared<SstableBuilder>(&loop, filepath);

    std::string value(4069, 'x');           // key(1) + value(4069) = 4070 -> fits exactly
    EXPECT_TRUE(builder->add(s_of("k"), s_of(value), 1).has_value());

    bool done = false;
    builder->finish([&](auto) { done = true; loop.stop(); });
    if (!done) loop.run();

    auto reader = std::make_shared<SstableReader>(&loop, filepath);
    bool init_done = false;
    reader->init([&](auto) { init_done = true; loop.stop(); });
    if (!init_done) loop.run();

    bool get_done = false;
    reader->get(s_of("k"), [&](auto r) {
        ASSERT_TRUE(r.has_value());
        EXPECT_EQ(r->size(), 4069u);
        get_done = true;
        loop.stop();
    });
    if (!get_done) loop.run();
    EXPECT_TRUE(get_done);
    std::filesystem::remove(filepath);
}

TEST(SstableLargeValueTest, ValueOverLimitIsRejected) {
    EventLoop loop(1024);
    std::string filepath = "test_lv_2.sst";
    auto builder = std::make_shared<SstableBuilder>(&loop, filepath);

    std::string value(4070, 'x');           // key+value = 4071 -> no longer fits
    auto res = builder->add(s_of("k"), s_of(value), 1);
    EXPECT_FALSE(res.has_value());
    EXPECT_EQ(res.error(), make_error_code(StorageError::kValueTooLarge));
    std::filesystem::remove(filepath);
}

TEST(SstableLargeValueTest, BuilderWorksAfterRejection) {
    EventLoop loop(1024);
    std::string filepath = "test_lv_4.sst";
    auto builder = std::make_shared<SstableBuilder>(&loop, filepath);

    std::string huge(8192, 'x');
    EXPECT_FALSE(builder->add(s_of("big"), s_of(huge), 1).has_value());

    EXPECT_TRUE(builder->add(s_of("small"), s_of("value"), 2).has_value());  // builder still alive

    bool done = false;
    builder->finish([&](auto r) { EXPECT_TRUE(r.has_value()); done = true; loop.stop(); });
    if (!done) loop.run();
    EXPECT_TRUE(done);
    std::filesystem::remove(filepath);
}